from pydantic import BaseModel

class Book(BaseModel):
    name: str
    authors: list[str]
```

**TypeScript**

```typescript
import { z } from 'zod';

const Book = z.object({
  name: z.string(),
  authors: z.array(z.string()),
});
```

**curl json schema**

```json
{
  "type": "json_schema",
  "json_schema": {
    "schema": {
      "properties": {
        "name": {
          "title": "Name",
          "type": "string"
        },
        "authors": {
          "items": {
            "type": "string"
          },
          "title": "Authors",
          "type": "array"
        }
      },
      "required": [
        "name",
        "authors"
      ],
      "title": "Book",
      "type": "object",
      "additionalProperties": false
