  role: 'tool' as const,
  name: toolCall.function.name,
  content: JSON.stringify(result),
  toolCallId: toolCall.id,
});

const finalResponse = await client.chat.complete({
  model: 'mistral-medium-latest',
  messages,
  tools,
});

